def split_lowerstring(s: str) -> list[str]:
    result = []
    current = ""

    for char in s:
        if char.islower():
            current += char
        else:
            if current:
                result.append(current)
                current = ""
            if char.isupper():
                current = char

    if current:
        result.append(current)

    return result

def remove_dirty_chars(first_str: str, second_str: str) -> str:
    """Remove characters from first string which are present in second string."""
    chars_to_remove = set(second_str)
    return ''.join(char for char in first_str if char not in chars_to_remove)

