def anagram_combos(words, w):
    from collections import Counter

    k = len(words[0])
    n = len(w)
    target_counter = Counter(w)
    word_counters = {word: Counter(word) for word in words}

    memo = {}

    def backtrack(remaining_counter, words_used):
        key = (tuple(sorted(remaining_counter.items())), tuple(sorted(words_used)))
        if key in memo:
            return memo[key]

        # Base case: no characters left to match
        if all(count == 0 for count in remaining_counter.values()):
            return 1

        # Check if any character has negative count (shouldn't happen in correct recursion)
        if any(count < 0 for count in remaining_counter.values()):
            return 0

        count = 0
        for word in words:
            word_counter = word_counters[word]

            # Check if this word can be used (all its characters are available)
            can_use = True
            for char, char_count in word_counter.items():
                if remaining_counter.get(char, 0) < char_count:
                    can_use = False
                    break

            if can_use:
                # Use this word
                new_remaining = remaining_counter.copy()
                for char, char_count in word_counter.items():
                    new_remaining[char] -= char_count

                new_words_used = words_used + (word,)
                count += backtrack(new_remaining, new_words_used)

        memo[key] = count
        return count

    return backtrack(target_counter, ())

