def arrange_grades(students):
    if not students:
        return True

    n = len(students)
    m = len(students[0])

    # Sort each grade's students
    sorted_students = [sorted(grade) for grade in students]

    # Try to find a valid arrangement using backtracking
    def backtrack(grade_idx, prev_arrangement):
        if grade_idx == n:
            return True

        current_grade = sorted_students[grade_idx]

        # Generate all permutations of current grade
        from itertools import permutations

        for perm in permutations(current_grade):
            # Check if this permutation is valid
            valid = True
            if grade_idx > 0:
                for j in range(m):
                    if perm[j] <= prev_arrangement[j]:
                        valid = False
                        break

            if valid:
                if backtrack(grade_idx + 1, perm):
                    return True

        return False

    return backtrack(0, None)

def at_least_this_fast(input_list: list[tuple[float, float]]) -> float:
    if len(input_list) < 2:
        return 0

    max_speed = 0
    for i in range(1, len(input_list)):
        time_prev, location_prev = input_list[i - 1]
        time_curr, location_curr = input_list[i]

        time_diff = time_curr - time_prev
        location_diff = abs(location_curr - location_prev)

        if time_diff > 0:
            speed = location_diff / time_diff
            max_speed = max(max_speed, speed)

    return max_speed

def cheapest_connection(connections, costs, durations):
    from heapq import heappush, heappop

    # Build adjacency list
    graph = {}
    for i, (src, dst) in enumerate(connections):
        if src not in graph:
            graph[src] = []
        graph[src].append((dst, costs[i], durations[i]))

    # Dijkstra's algorithm with modified cost function
    # cost = ticket_cost + duration_in_minutes * (100/60) dollars per minute
    # = ticket_cost + duration_in_minutes * (5/3) dollars

    start = "New York"
    end = "Melbourne"

    # Priority queue: (total_cost, total_duration, current_city, path)
    pq = [(0, 0, start, [start])]
    visited = set()

    while pq:
        ticket_cost, duration, city, path = heappop(pq)

        if city in visited:
            continue
        visited.add(city)

        if city == end:
            return path

        if city in graph:
            for next_city, flight_cost, flight_duration in graph[city]:
                if next_city not in visited:
                    new_ticket_cost = ticket_cost + flight_cost
                    new_duration = duration + flight_duration
                    # Total cost = ticket cost + duration in hours * 100
                    total_cost = new_ticket_cost + (new_duration / 60) * 100
                    new_path = path + [next_city]
                    heappush(pq, (total_cost, new_duration, next_city, new_path))

    return []

