def has_diff_path(root: TreeNode) -> bool:
    def dfs(node, prev_diff):
        if node is None:
            return False

        # Calculate diff of current node
        left_val = node.left.val if node.left else 0
        right_val = node.right.val if node.right else 0
        current_diff = abs(left_val - right_val)

        # Check if current diff is greater than previous diff
        # (skip this check if node is root, i.e., prev_diff is -1)
        if prev_diff != -1 and current_diff <= prev_diff:
            return False

        # If leaf node, we found a valid path
        if node.left is None and node.right is None:
            return True

        # Recursively check left and right subtrees
        return dfs(node.left, current_diff) or dfs(node.right, current_diff)

    if root is None:
        return False

    return dfs(root, -1)

class TreeNode:
