            else:
                self.left.add_node(x)
        else:
            if self.right is None:
                self.right = TreeNode(x)
            else:
                self.right.add_node(x)


def get_all_elements_in_range(root: TreeNode, range_tuple: tuple) -> set:
    start, end = range_tuple
    result = set()

    def dfs(node):
        if node is None:
            return

        # If current node's value is within range, add it
        if start <= node.val <= end:
            result.add(node.val)

        # If current node's value is greater than start, explore left subtree
        if node.val > start:
            dfs(node.left)

        # If current node's value is less than end, explore right subtree
        if node.val < end:
            dfs(node.right)

    dfs(root)
    return result


