def can_reach_exit(board):
    if not board or not board[0]:
        return False, []

    rows, cols = len(board), len(board[0])
    target = (rows - 1, cols - 1)

    # BFS to find if we can reach the target and track the path
    from collections import deque

    queue = deque([(0, 0, [(0, 0)])])
    visited = {(0, 0)}

    while queue:
        row, col, path = queue.popleft()

        if (row, col) == target:
            return True, path

        max_move = board[row][col]

        # Try moving down
        for next_row in range(row + 1, min(row + max_move + 1, rows)):
            if (next_row, col) not in visited:
                visited.add((next_row, col))
                queue.append((next_row, col, path + [(next_row, col)]))

        # Try moving right
        for next_col in range(col + 1, min(col + max_move + 1, cols)):
            if (row, next_col) not in visited:
                visited.add((row, next_col))
                queue.append((row, next_col, path + [(row, next_col)]))

    return False, []

