def chess_attacks(board):
    def get_attacking_squares(row, col, piece):
        """Return all squares that a piece at (row, col) can attack"""
        attacking = set()

        if piece == 'K':  # King
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = row + dr, col + dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        attacking.add((nr, nc))

        elif piece == 'Q':  # Queen
            # Horizontal and vertical
            for dc in range(8):
                if dc != col:
                    attacking.add((row, dc))
            for dr in range(8):
                if dr != row:
                    attacking.add((dr, col))
            # Diagonals
            for dr in range(8):
                for dc in range(8):
                    if abs(dr - row) == abs(dc - col) and (dr != row or dc != col):
                        attacking.add((dr, dc))

        elif piece == 'R':  # Rook
            # Horizontal and vertical
            for dc in range(8):
                if dc != col:
                    attacking.add((row, dc))
            for dr in range(8):
                if dr != row:
                    attacking.add((dr, col))

        elif piece == 'B':  # Bishop
            # Diagonals
            for dr in range(8):
                for dc in range(8):
                    if abs(dr - row) == abs(dc - col) and (dr != row or dc != col):
                        attacking.add((dr, dc))

        elif piece == 'N':  # Knight
            knight_moves = [
                (-2, -1), (-2, 1), (-1, -2), (-1, 2),
                (1, -2), (1, 2), (2, -1), (2, 1)
            ]
            for dr, dc in knight_moves:
                nr, nc = row + dr, col + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    attacking.add((nr, nc))

        return attacking

    # Find all pieces
    pieces_by_type = {}
    for row in range(8):
        for col in range(8):
            piece = board[row][col]
            if piece != '.':
                if piece not in pieces_by_type:
                    pieces_by_type[piece] = []
                pieces_by_type[piece].append((row, col))

    # Check if any two pieces of the same type attack each other
    for piece_type, positions in pieces_by_type.items():
        if len(positions) < 2:
            continue

        for i, (row1, col1) in enumerate(positions):
            attacking = get_attacking_squares(row1, col1, piece_type)
            for j, (row2, col2) in enumerate(positions):
                if i != j and (row2, col2) in attacking:
                    return True

    return False

def clockwise_spiral(n):
    matrix = [[0] * n for _ in range(n)]
    num = 1
    top, bottom, left, right = 0, n - 1, 0, n - 1

    while top <= bottom and left <= right:
        # Fill corners first
        if top <= bottom and left <= right:
            matrix[top][left] = num
            num += 1
        if top <= bottom and left <= right:
            matrix[top][right] = num
            num += 1
        if top <= bottom and left <= right:
            matrix[bottom][right] = num
            num += 1
        if top <= bottom and left <= right:
            matrix[bottom][left] = num
            num += 1

        # Fill edges (non-corners) clockwise
        # Top edge (left to right, excluding corners)
        for col in range(left + 1, right):
            if top <= bottom and left <= right:
                matrix[top][col] = num
                num += 1

        # Right edge (top to bottom, excluding corners)
        for row in range(top + 1, bottom):
            if top <= bottom and left <= right:
                matrix[row][right] = num
                num += 1

        # Bottom edge (right to left, excluding corners)
        for col in range(right - 1, left, -1):
            if top <= bottom and left <= right:
                matrix[bottom][col] = num
                num += 1

        # Left edge (bottom to top, excluding corners)
        for row in range(bottom - 1, top, -1):
            if top <= bottom and left <= right:
                matrix[row][left] = num
                num += 1

        # Move to next inner square
        top += 1
        bottom -= 1
        left += 1
        right -= 1

    return matrix

class ClosestToKStack:
    def __init__(self, k: int):
        self.k = k
        self.stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)

    def pop(self) -> None:
        if self.stack:
            self.stack.pop()

    def top(self) -> int:
        if self.stack:
            return self.stack[-1]
        return -1

    def get_closest_to_k(self) -> int:
        if not self.stack:
            return -1

        closest = self.stack[0]
        min_diff = abs(self.stack[0] - self.k)

        for val in self.stack:
            diff = abs(val - self.k)
            if diff < min_diff:
                min_diff = diff
                closest = val

        return closest


