def collect_numbers_by_factors(factors: list[int], numbers_to_collect: list[int]) -> dict[int, list[int]]:
    result = {}
    for factor in factors:
        if factor != 0:  # Avoid division by zero
            multiples = sorted([num for num in numbers_to_collect if num % factor == 0])
            result[factor] = multiples
        else:
            result[factor] = []
    return result

