def form_words_from_magazine(target, candidates):
    from collections import Counter

    target_counter = Counter(target)
    target_len = len(target)
    n = len(candidates)

    # Precompute letter counts and lengths for each candidate word
    word_counts = []
    word_lens = []
    for w in candidates:
        word_counts.append(Counter(w))
        word_lens.append(len(w))

    best = None  # minimum unused letters found

    # Try all subsets of candidates (n < 20, so 2^n is feasible)
    for mask in range(1, 1 << n):
        combined = Counter()
        total_len = 0
        for i in range(n):
            if mask & (1 << i):
                combined.update(word_counts[i])
                total_len += word_lens[i]

        # Check if combined letters can cover the target word
        can_form = True
        for ch, cnt in target_counter.items():
            if combined.get(ch, 0) < cnt:
                can_form = False
                break

        if can_form:
            unused = total_len - target_len
            if unused >= 0:
                if best is None or unused < best:
                    best = unused

    return best if best is not None else -1

