def at_least_this_fast(input_list: List[Tuple[float, float]]) -> float:
    max_speed = 0.0
    for i in range(1, len(input_list)):
        t0, x0 = input_list[i - 1]
        t1, x1 = input_list[i]
        dt = t1 - t0
        if dt == 0:
