    return max_speed

def are_targets_obtainable(targets, coins, k):
    if not targets:
        return []

    max_target = max(targets)

    # min_coins[i] = minimum number of coins needed to make value i
    min_coins = [float('inf')] * (max_target + 1)
    min_coins[0] = 0

    for i in range(1, max_target + 1):
        for c in coins:
            if c <= i and min_coins[i - c] + 1 < min_coins[i]:
                min_coins[i] = min_coins[i - c] + 1

    result = []
    for t in targets:
        if t <= max_target and min_coins[t] <= k:
            result.append(True)
        else:
            result.append(False)

    return result

