def has_diff_path(root: TreeNode) -> bool:
    def get_diff(node: TreeNode) -> int:
        left_val = node.left.val if node.left else 0
        right_val = node.right.val if node.right else 0
        return abs(left_val - right_val)

    def is_leaf(node: TreeNode) -> bool:
        return node.left is None and node.right is None

    def helper(node: TreeNode, prev_diff) -> bool:
        if is_leaf(node):
            return True

        current_diff = get_diff(node)

        if prev_diff is not None and current_diff <= prev_diff:
            return False

        left_ok = node.left is not None and helper(node.left, current_diff)
        right_ok = node.right is not None and helper(node.right, current_diff)

        return left_ok or right_ok

    if root is None:
        return False

    return helper(root, None)

