def get_all_elements_in_range(root: TreeNode, r: tuple) -> set:
    start, end = r
    result = set()

    def traverse(node):
        if node is None:
            return
        if node.val > start:
            traverse(node.left)
        if start <= node.val <= end:
            result.add(node.val)
        if node.val < end:
            traverse(node.right)

    traverse(root)
    return result

