def can_reach_exit(board):
    if not board or not board[0]:
        return False, []

    rows = len(board)
    cols = len(board[0])
    target = (rows - 1, cols - 1)
    path = []

    def dfs(r, c):
        path.append((r, c))

        if (r, c) == target:
            return True

        max_step = board[r][c]

        # Try moving down first, with increasing step sizes
        for step in range(1, max_step + 1):
            nr, nc = r + step, c
            if nr < rows:
                if dfs(nr, nc):
                    return True

        # Then try moving right, with increasing step sizes
        for step in range(1, max_step + 1):
            nr, nc = r, c + step
            if nc < cols:
                if dfs(nr, nc):
                    return True

        path.pop()
        return False

    if dfs(0, 0):
        return True, path
    else:
        return False, []

