class BowlingAlley:
    def __init__(self, shoes: list[tuple[int, int]], num_alleys: int):
        self.shoe_inventory = dict(shoes)  # size -> total pairs available
        self.num_alleys = num_alleys
        self.schedule = {}  # timestamp -> set of booking_ids
        self.bookings = {}  # booking_id -> (shoes list, timestamp)
        self.next_id = 1
        self.alley_usage = {}  # timestamp -> count of alleys used
        self.shoe_usage = {}   # timestamp -> {size: count used}

    def book_alley(self, shoes: list[int], timestamp: int) -> int:
        alleys_used = self.alley_usage.get(timestamp, 0)
        if alleys_used >= self.num_alleys:
            return -1

        shoe_usage_t = self.shoe_usage.get(timestamp, {})
        needed = {}
        for s in shoes:
            needed[s] = needed.get(s, 0) + 1

        for size, count in needed.items():
            available = self.shoe_inventory.get(size, 0)
            used = shoe_usage_t.get(size, 0)
            if used + count > available:
                return -1

        booking_id = self.next_id
        self.next_id += 1

        self.alley_usage[timestamp] = alleys_used + 1

        if timestamp not in self.shoe_usage:
            self.shoe_usage[timestamp] = {}
        for size, count in needed.items():
            self.shoe_usage[timestamp][size] = self.shoe_usage[timestamp].get(size, 0) + count

        if timestamp not in self.schedule:
            self.schedule[timestamp] = set()
        self.schedule[timestamp].add(booking_id)

        self.bookings[booking_id] = (shoes, timestamp)

        return booking_id

    def delete_booking(self, booking_id: int) -> None:
        if booking_id not in self.bookings:
            return

        shoes, timestamp = self.bookings[booking_id]

        self.alley_usage[timestamp] -= 1

        needed = {}
        for s in shoes:
            needed[s] = needed.get(s, 0) + 1

        for size, count in needed.items():
            self.shoe_usage[timestamp][size] -= count

        self.schedule[timestamp].discard(booking_id)
        if not self.schedule[timestamp]:
            del self.schedule[timestamp]

        del self.bookings[booking_id]

class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        # key -> [value, insertion_timestamp, access_count]
        self.cache = {}

    def get(self, key: int, timestamp: int) -> int:
        if key not in self.cache:
            return -1
        entry = self.cache[key]
        entry[2] += 1  # increment usage count
        return entry[0]

    def put(self, key: int, value: int, timestamp: int) -> None:
        if key in self.cache:
            # update existing entry's value and usage count
            self.cache[key][0] = value
            self.cache[key][2] += 1
            return

        if len(self.cache) < self.capacity:
            self.cache[key] = [value, timestamp, 1]
            return

        # Cache is full - find eviction candidates (in cache for >= 10 seconds)
        eligible = [
            (k, v) for k, v in self.cache.items()
            if timestamp - v[1] >= 10
        ]

        if not eligible:
            # No entry is old enough to be evicted; do not insert new entry
            return

        # Find the entry with the lowest usage-per-second rate
        min_key = None
        min_rate = None
        for k, v in eligible:
            age = timestamp - v[1]
            rate = v[2] / age if age > 0 else float('inf')
            if min_rate is None or rate < min_rate:
                min_rate = rate
                min_key = k

        del self.cache[min_key]
        self.cache[key] = [value, timestamp, 1]

def calculateCommand(currentState, desiredState):
    def swap_pairs(x):
        result = x  # preserve any bits beyond the 32-bit range unchanged
        for i in range(0, 32, 2):
            bit0 = (x >> i) & 1
            bit1 = (x >> (i + 1)) & 1
            # clear the two bits first
            result &= ~(1 << i) & ~(1 << (i + 1))
            # set them swapped
            result |= (bit0 << (i + 1)) | (bit1 << i)
        return result

    diff = currentState ^ desiredState
    return swap_pairs(diff)


def applyCommandToState(command, state):
    def swap_pairs(x):
        result = x
        for i in range(0, 32, 2):
            bit0 = (x >> i) & 1
            bit1 = (x >> (i + 1)) & 1
            result &= ~(1 << i) & ~(1 << (i + 1))
            result |= (bit0 << (i + 1)) | (bit1 << i)
        return result

    return state ^ swap_pairs(command)

from typing import List
from collections import deque

def can_exit_maze(maze: List[List[bool]], start: List[int], exit: List[int]) -> bool:
    if not maze or not maze[0]:
        raise ValueError("Maze is empty")

    rows = len(maze)
    cols = len(maze[0])

    def in_bounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    if not in_bounds(start):
        raise ValueError("Start position is not in the maze")
    if not in_bounds(exit):
        raise ValueError("Exit position is not in the maze")

    sr, sc = start
    er, ec = exit

    if maze[sr][sc] == 0 or maze[er][ec] == 0:
        return False

    if start == exit:
        return True

    visited = [[False] * cols for _ in range(rows)]
    visited[sr][sc] = True
    queue = deque([(sr, sc)])

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and maze[nr][nc] == 1:
                if [nr, nc] == exit:
                    return True
                visited[nr][nc] = True
                queue.append((nr, nc))

    return False

def cheapest_connection(nodes, edges):
    n = len(nodes)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        parent[rx] = ry
        return True

    # Union existing edges - these are free (already connected)
    for u, v in edges:
        union(u, v)

    # Build all possible candidate edges (complete graph) with XOR weight
    all_edges = []
    for i in range(n):
        for j in range(i + 1, n):
            w = nodes[i] ^ nodes[j]
            all_edges.append((w, i, j))
    all_edges.sort()

    total = 0
    for w, i, j in all_edges:
        if find(i) != find(j):
            union(i, j)
            total += w

    return total

def max_reactions(chemicals, reactions):
    from collections import defaultdict

    graph = defaultdict(list)
    for a, b in reactions:
        graph[a].append(b)

    memo = {}

    def longest_path(node):
        if node in memo:
            return memo[node]
        max_len = 0
        for neighbor in graph[node]:
            max_len = max(max_len, 1 + longest_path(neighbor))
        memo[node] = max_len
        return max_len

    result = 0
    for chem in chemicals:
        result = max(result, longest_path(chem))

    return result

def chess_attacks(board):
    def get_positions(piece_type):
        positions = []
        for r in range(8):
            for c in range(8):
                if board[r][c] == piece_type:
                    positions.append((r, c))
        return positions

    def is_path_clear(r1, c1, r2, c2):
        dr = r2 - r1
        dc = c2 - c1
        step_r = (dr > 0) - (dr < 0)
        step_c = (dc > 0) - (dc < 0)
        r, c = r1 + step_r, c1 + step_c
        while (r, c) != (r2, c2):
            if board[r][c] != '.':
                return False
            r += step_r
            c += step_c
        return True

    def knight_attacks(r1, c1, r2, c2):
        dr = abs(r1 - r2)
        dc = abs(c1 - c2)
        return (dr, dc) in [(1, 2), (2, 1)]

    def king_attacks(r1, c1, r2, c2):
        dr = abs(r1 - r2)
        dc = abs(c1 - c2)
        return max(dr, dc) == 1

    def rook_attacks(r1, c1, r2, c2):
        if r1 == r2 or c1 == c2:
            return is_path_clear(r1, c1, r2, c2)
        return False

    def bishop_attacks(r1, c1, r2, c2):
        if abs(r1 - r2) == abs(c1 - c2):
            return is_path_clear(r1, c1, r2, c2)
        return False

    def queen_attacks(r1, c1, r2, c2):
        return rook_attacks(r1, c1, r2, c2) or bishop_attacks(r1, c1, r2, c2)

    piece_attack_funcs = {
        'N': knight_attacks,
        'K': king_attacks,
        'R': rook_attacks,
        'B': bishop_attacks,
        'Q': queen_attacks,
    }

    for piece, func in piece_attack_funcs.items():
        positions = get_positions(piece)
        for i in range(len(positions)):
            for j in range(i + 1, len(positions)):
                r1, c1 = positions[i]
                r2, c2 = positions[j]
                if func(r1, c1, r2, c2):
                    return True
    return False

class ClosestToKStack:
    def __init__(self, k: int):
        self.k = k
        self.stack = []
        self.closest_stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        if not self.closest_stack:
            self.closest_stack.append(val)
        else:
            current_closest = self.closest_stack[-1]
            if abs(val - self.k) < abs(current_closest - self.k):
                self.closest_stack.append(val)
            else:
                self.closest_stack.append(current_closest)

    def pop(self) -> None:
        if self.stack:
            self.stack.pop()
            self.closest_stack.pop()

    def top(self) -> int:
        if self.stack:
            return self.stack[-1]
        return -1

    def get_closest_to_k(self):
        if self.closest_stack:
            return self.closest_stack[-1]
        return -1

