from collections import Counter

def anagram_combos(words, w):
    k = len(words[0]) if words else 0
    if k == 0 or len(w) % k != 0:
        return 0
    m = len(w) // k
    target = Counter(w)
    counts = [Counter(x) for x in words]
    n = len(words)

    def fits(c, rem):
        return all(rem[ch] >= v for ch, v in c.items())

    def rec(i, rem, left):
        if left == 0:
            return 1 if not +rem else 0
        if n - i < left:
            return 0
        total = 0
        for j in range(i, n):
            c = counts[j]
            if fits(c, rem):
                total += rec(j + 1, rem - c, left - 1)
        return total

    return rec(0, target, m)

