def form_words_from_magazine(target, words):
    need = Counter(target)
    n = len(words)
    best = None
    for mask in range(1 << n):
        pool = Counter()
        total = 0
        for i in range(n):
            if mask & (1 << i):
                pool.update(words[i])
                total += len(words[i])
        if all(pool[c] >= need[c] for c in need):
            unused = total - len(target)
            if best is None or unused < best:
                best = unused
    return best

