def are_targets_obtainable(targets, coins, k):
    if not targets:
        return []
    m = max(targets)
    INF = float('inf')
    dp = [INF] * (m + 1)
    dp[0] = 0
    for i in range(1, m + 1):
        for c in coins:
            if c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return [dp[t] <= k for t in targets]

