def cheapest_connection(flights, costs, durations, start="New York", end="Melbourne"):
    graph = defaultdict(list)
    for (src, dst), c, d in zip(flights, costs, durations):
        graph[src].append((dst, c + d * 100.0 / 60.0))

    best = {start: 0.0}
    heap = [(0.0, start, [start])]
    while heap:
        weight, city, path = heapq.heappop(heap)
        if city == end:
            return path
        if weight > best.get(city, float("inf")):
            continue
        for nxt, w in graph[city]:
            nw = weight + w
            if nw < best.get(nxt, float("inf")):
                best[nxt] = nw
                heapq.heappush(heap, (nw, nxt, path + [nxt]))
    return None

def has_diff_path(root):
    class _:
        pass

    def diff(node):
        l = node.left.val if node.left else 0
        r = node.right.val if node.right else 0
        return abs(l - r)

    def helper(node, prev):
        if node is None:
            return False
        if node.left is None and node.right is None:
            return True
        d = diff(node)
        if d <= prev:
            return False
        return helper(node.left, d) or helper(node.right, d)

    return helper(root, -1)


