def get_all_elements_in_range(root, rng):
    start, end = rng
    result = set()
    if root is None:
        return result
    if start <= root.val <= end:
        result.add(root.val)
    if root.val > start:
        result |= get_all_elements_in_range(root.left, rng)
    if root.val < end:
        result |= get_all_elements_in_range(root.right, rng)
    return result

