def can_reach_exit(board):
    if not board or not board[0]:
        return False, []
    rows, cols = len(board), len(board[0])
    target = (rows - 1, cols - 1)
    visited = set()
    path = []

    def dfs(r, c):
        if (r, c) in visited:
            return False
        visited.add((r, c))
        path.append((r, c))
        if (r, c) == target:
            return True
        step_max = board[r][c]
        for s in range(1, step_max + 1):
            if r + s < rows and dfs(r + s, c):
                return True
        for s in range(1, step_max + 1):
            if c + s < cols and dfs(r, c + s):
                return True
        path.pop()
        return False

    reached = dfs(0, 0)
    return (True, path) if reached else (False, [])

