from collections import defaultdict


class BowlingAlley:
    def __init__(self, shoes: list[tuple[int, int]], num_alleys: int):
        self.inventory = defaultdict(int)
        for size, count in shoes:
            self.inventory[size] += count
        self.num_alleys = num_alleys
        self.schedule = {}                      # timestamp -> set of booking ids
        self.bookings = {}                      # booking id -> (timestamp, shoes)
        self.used = defaultdict(lambda: defaultdict(int))  # timestamp -> size -> count
        self._next_id = 1

    def book_alley(self, shoes: list[int], timestamp: int) -> int:
        booked = self.schedule.get(timestamp, set())
        if len(booked) >= self.num_alleys:
            return -1

        needed = defaultdict(int)
        for size in shoes:
            needed[size] += 1

        used_at_ts = self.used[timestamp]
        for size, count in needed.items():
            if used_at_ts[size] + count > self.inventory.get(size, 0):
                return -1

        booking_id = self._next_id
        self._next_id += 1

        for size, count in needed.items():
            used_at_ts[size] += count

        self.schedule.setdefault(timestamp, set()).add(booking_id)
        self.bookings[booking_id] = (timestamp, list(shoes))
        return booking_id

    def delete_booking(self, booking_id: int) -> None:
        if booking_id not in self.bookings:
            return
        timestamp, shoes = self.bookings.pop(booking_id)
        for size in shoes:
            self.used[timestamp][size] -= 1
        self.schedule[timestamp].discard(booking_id)
        if not self.schedule[timestamp]:
            del self.schedule[timestamp]
            del self.used[timestamp]

