class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        # key -> [value, insert_timestamp, use_count, last_used_timestamp]
        self.cache = {}

    def get(self, key: int, timestamp: int) -> int:
        entry = self.cache.get(key)
        if entry is None:
            return -1
        entry[2] += 1
        entry[3] = timestamp
        return entry[0]

    def put(self, key: int, value: int, timestamp: int) -> None:
        entry = self.cache.get(key)
        if entry is not None:
            entry[0] = value
            entry[2] += 1
            entry[3] = timestamp
            return

        if len(self.cache) >= self.capacity:
            candidates = [k for k, v in self.cache.items()
                          if timestamp - v[1] >= 10]
            if not candidates:
                return
            victim = min(
                candidates,
                key=lambda k: (self.cache[k][2] / (timestamp - self.cache[k][1]),
                               self.cache[k][3])
            )
            del self.cache[victim]

        self.cache[key] = [value, timestamp, 1, timestamp]

from typing import List
from collections import deque


def can_exit_maze(maze: List[List[bool]], start: List[int], exit: List[int]) -> bool:
    if not maze or not maze[0]:
        raise ValueError("Maze is empty")

    rows, cols = len(maze), len(maze[0])

    def in_maze(pos):
        return (
            isinstance(pos, (list, tuple))
            and len(pos) == 2
            and 0 <= pos[0] < rows
            and 0 <= pos[1] < cols
        )

    if not in_maze(start) or not in_maze(exit):
        raise ValueError("Start or exit position is not in the maze")

    start = (start[0], start[1])
    exit = (exit[0], exit[1])

    if not maze[start[0]][start[1]] or not maze[exit[0]][exit[1]]:
        return False

    visited = {start}
    queue = deque([start])

    while queue:
        r, c = queue.popleft()
        if (r, c) == exit:
            return True
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and maze[nr][nc]:
                visited.add((nr, nc))
                queue.append((nr, nc))

    return False

def cheapest_connection(nodes, edges):
    n = len(nodes)
    if n == 0:
        return 0

    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for u, v in edges:
        union(u, v)

    comps = {}
    for i in range(n):
        comps.setdefault(find(i), []).append(nodes[i])
    groups = list(comps.values())
    k = len(groups)
    if k <= 1:
        return 0

    cost = [[0] * k for _ in range(k)]
    for i in range(k):
        for j in range(i + 1, k):
            best = min(a ^ b for a in groups[i] for b in groups[j])
            cost[i][j] = cost[j][i] = best

    INF = float('inf')
    in_tree = [False] * k
    dist = [INF] * k
    dist[0] = 0
    total = 0
    for _ in range(k):
        u = min((d, i) for i, d in enumerate(dist) if not in_tree[i])[1]
        in_tree[u] = True
        total += dist[u]
        for v in range(k):
            if not in_tree[v] and cost[u][v] < dist[v]:
                dist[v] = cost[u][v]
    return total

def max_reactions(chemicals, reactions):
    graph = {c: [] for c in chemicals}
    for a, b in reactions:
        graph.setdefault(a, []).append(b)
        graph.setdefault(b, [])

    memo = {}

    def longest(node):
        if node in memo:
            return memo[node]
        best = 0
        for nxt in graph.get(node, []):
            best = max(best, 1 + longest(nxt))
        memo[node] = best
        return best

    return max((longest(c) for c in graph), default=0)

def chess_attacks(board):
    n = 8
    rook_dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    bishop_dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
    knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                    (1, -2), (1, 2), (2, -1), (2, 1)]

    for r in range(n):
        for c in range(n):
            p = board[r][c]
            if p == '.':
                continue
            if p == 'N':
                for dr, dc in knight_moves:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == 'N':
                        return True
            elif p == 'K':
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == 'K':
                            return True
            else:
                if p == 'R':
                    dirs = rook_dirs
                elif p == 'B':
                    dirs = bishop_dirs
                else:
                    dirs = rook_dirs + bishop_dirs
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    while 0 <= nr < n and 0 <= nc < n:
                        q = board[nr][nc]
                        if q != '.':
                            if q == p:
                                return True
                            break
                        nr += dr
                        nc += dc
    return False

class ClosestToKStack:
    def __init__(self, k: int):
        self.k = k
        self._stack = []
        self._closest = []  # parallel stack holding closest-to-k value so far

    def push(self, val: int) -> None:
        self._stack.append(val)
        if not self._closest:
            self._closest.append(val)
        else:
            best = self._closest[-1]
            if abs(val - self.k) < abs(best - self.k):
                self._closest.append(val)
            else:
                self._closest.append(best)

    def pop(self) -> None:
        if not self._stack:
            return None
        self._closest.pop()
        return self._stack.pop()

    def top(self) -> int:
        if not self._stack:
            return -1
        return self._stack[-1]

    def get_closest_to_k(self):
        if not self._closest:
            return -1
        return self._closest[-1]

