def has_diff_path(root: TreeNode) -> bool:
    if not root:
        return False

    def dfs(node, prev_diff):
        if not node:
            return False
        if not node.left and not node.right:
            return True

        left_val = node.left.val if node.left else 0
        right_val = node.right.val if node.right else 0
        curr_diff = abs(left_val - right_val)

        if curr_diff <= prev_diff:
            return False

        return dfs(node.left, curr_diff) or dfs(node.right, curr_diff)

    return dfs(root, -1)

class TreeNode:

