        self.val = x
        self.left = None
        self.right = None

    def add_node(self, x: int):
        if x < self.val:
            if self.left is None:
                self.left = TreeNode(x)
            else:
                self.left.add_node(x)
        elif x > self.val:
            if self.right is None:
                self.right = TreeNode(x)
            else:
                self.right.add_node(x)


def get_all_elements_in_range(root: TreeNode, rng: tuple) -> set:
    start, end = rng
    result = set()

    def dfs(node):
        if not node:
            return
        if start <= node.val <= end:
            result.add(node.val)
        if node.val > start:
            dfs(node.left)
        if node.val < end:
            dfs(node.right)

    dfs(root)
    return result

