def can_reach_exit(board):
    R, C = len(board), len(board[0])
    target = (R - 1, C - 1)
    visited = set()

    def dfs(r, c):
        if (r, c) == target:
            return [(r, c)]

        visited.add((r, c))
        k = board[r][c]

        for d in range(1, k + 1):
            nr, nc = r + d, c
            if nr < R and (nr, nc) not in visited:
                sub_path = dfs(nr, nc)
                if sub_path is not None:
                    return [(r, c)] + sub_path

        for d in range(1, k + 1):
            nr, nc = r, c + d
            if nc < C and (nr, nc) not in visited:
                sub_path = dfs(nr, nc)
                if sub_path is not None:
                    return [(r, c)] + sub_path

        return None

    path = dfs(0, 0)
    if path is not None:
        return True, path
    return False, None

