def can_exit_maze(maze: List[List[bool]], start: List[int], exit: List[int]) -> bool:
    if not maze or not maze[0]:
        raise ValueError("Maze is empty")

    rows, cols = len(maze), len(maze[0])
    sr, sc = start
    er, ec = exit

    if not (0 <= sr < rows and 0 <= sc < cols):
        raise ValueError("Start position is not in the maze")
    if not (0 <= er < rows and 0 <= ec < cols):
        raise ValueError("Exit position is not in the maze")

    if not maze[sr][sc] or not maze[er][ec]:
        return False

    queue = deque([(sr, sc)])
    visited = {(sr, sc)}

    while queue:
        r, c = queue.popleft()
        if r == er and c == ec:
            return True

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and maze[nr][nc] and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

    return False

def cheapest_connection(nodes, edges):
    n = len(nodes)
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    comp_map = {}
    for i in range(n):
        r = find(i)
        if r not in comp_map:
            comp_map[r] = len(comp_map)

    k = len(comp_map)
    if k <= 1:
        return 0

    comp = [comp_map[find(i)] for i in range(n)]
    min_edge = {}
    for i in range(n):
        c1 = comp[i]
        v1 = nodes[i]
        for j in range(i + 1, n):
            c2 = comp[j]
            if c1 != c2:
                key = (c1, c2) if c1 < c2 else (c2, c1)
                w = v1 ^ nodes[j]
                if key not in min_edge or w < min_edge[key]:
                    min_edge[key] = w

    c_edges = sorted((w, c1, c2) for (c1, c2), w in min_edge.items())
    c_parent = list(range(k))

    def c_find(i):
        if c_parent[i] == i:
            return i
        c_parent[i] = c_find(c_parent[i])
        return c_parent[i]

    ans = 0
    added = 0
    for w, c1, c2 in c_edges:
        r1, r2 = c_find(c1), c_find(c2)
        if r1 != r2:
            c_parent[r1] = r2
            ans += w
            added += 1
            if added == k - 1:
                break
    return ans

def max_reactions(chemicals, reactions):
    from collections import defaultdict

    adj = defaultdict(list)
    for u, v in reactions:
        adj[u].append(v)

    memo = {}

    def dfs(u):
        if u in memo:
            return memo[u]
        max_len = 0
        for v in adj[u]:
            max_len = max(max_len, 1 + dfs(v))
        memo[u] = max_len
        return max_len

    return max((dfs(c) for c in chemicals), default=0)

def chess_attacks(board):
    pieces = []
    for r in range(8):
        for c in range(8):
            if board[r][c] != ".":
                pieces.append((board[r][c], r, c))

    for i in range(len(pieces)):
        p1, r1, c1 = pieces[i]
        for j in range(i + 1, len(pieces)):
            p2, r2, c2 = pieces[j]
            if p1 != p2:
                continue

            dr, dc = abs(r1 - r2), abs(c1 - c2)

            if p1 == "K":
                if max(dr, dc) == 1:
                    return True
            elif p1 == "N":
                if (dr, dc) in ((1, 2), (2, 1)):
                    return True
            elif p1 in ("R", "B", "Q"):
                is_rook = r1 == r2 or c1 == c2
                is_bishop = dr == dc and dr > 0

                if p1 == "R" and not is_rook:
                    continue
                if p1 == "B" and not is_bishop:
                    continue
                if p1 == "Q" and not (is_rook or is_bishop):
                    continue

                sr = 0 if r1 == r2 else (1 if r2 > r1 else -1)
                sc = 0 if c1 == c2 else (1 if c2 > c1 else -1)

                curr_r, curr_c = r1 + sr, c1 + sc
                blocked = False
                while (curr_r, curr_c) != (r2, c2):
                    if board[curr_r][curr_c] != ".":
                        blocked = True
                        break
                    curr_r += sr
                    curr_c += sc

                if not blocked:
                    return True

    return False

class ClosestToKStack:

    def __init__(self, k: int):
        self.k = k
        self.stack = []
        self.min_stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        if not self.min_stack:
            self.min_stack.append(val)
        else:
            best = self.min_stack[-1]
            if abs(val - self.k) < abs(best - self.k):
                self.min_stack.append(val)
            else:
                self.min_stack.append(best)

    def pop(self) -> None:
        if self.stack:
            self.stack.pop()
            self.min_stack.pop()

    def top(self) -> int:
        return self.stack[-1] if self.stack else -1

    def get_closest_to_k(self) -> int:
        return self.min_stack[-1] if self.min_stack else -1

