        item for item, freq in heapq.nlargest(k, counter.items(), key=lambda x: x[1])
    ]

def max_Prime_Factors(n):
    largest = 1
    d = 2
    while d * d <= n:
        while (n % d) == 0:
            largest = d
            n //= d
        d += 1
    if n > 1:
        largest = n
    return largest

def find_Nth_Digit(numerator: int, denominator: int, n: int) -> int:
    remainder = numerator % denominator
    for _ in range(n - 1):
        remainder = (remainder * 10) % denominator
    return (remainder * 10) // denominator

