def anagram_combos(words, w):
    k = len(words[0])
    n = len(w)

    target_count = Counter(w)

    word_counts = []
    for word in words:
        c = Counter(word)
        if all(c[char] <= target_count[char] for char in c):
            word_counts.append(c)

    memo = {}

    def solve(target_c, start_idx):
        if not target_c:
            return 1
        if start_idx == len(word_counts):
            return 0

        state = (
            tuple(sorted(target_c.items())),
            start_idx,
        )
        if state in memo:
            return memo[state]

        ans = 0
        wc = word_counts[start_idx]

        possible = True
        for char, count in wc.items():
            if target_c[char] < count:
                possible = False
                break

        if possible:
            new_target = target_c.copy()
            for char, count in wc.items():
                new_target[char] -= count
                if new_target[char] == 0:
                    del new_target[char]
            ans += solve(new_target, start_idx)

        ans += solve(target_c, start_idx + 1)

        memo[state] = ans
        return ans

    return solve(target_count, 0)

from collections import Counter

def form_words_from_magazine(target, candidates):
    target_counts = Counter(target)
    candidate_counts = [Counter(c) for c in candidates]
    n = len(candidates)

    min_unused = float('inf')

    for i in range(1, 1 << n):
        subset_count = Counter()
        for j in range(n):
            if (i >> j) & 1:
                subset_count += candidate_counts[j]

        # Check if subset can form target
        valid = True
        for char, count in target_counts.items():
            if subset_count[char] < count:
                valid = False
                break

        if valid:
            total_letters = sum(subset_count.values())
            unused = total_letters - len(target)
            if unused < min_unused:
                min_unused = unused

    return min_unused if min_unused != float('inf') else -1

