def at_least_this_fast(input_list: List[Tuple[float, float]]) -> float:
    max_speed = 0.0
    for i in range(len(input_list) - 1):
        t1, x1 = input_list[i]
        t2, x2 = input_list[i+1]
        dt = t2 - t1
