def are_targets_obtainable(targets: list[int], coins: list[int], k: int) -> list[int]:
    max_target = max(targets) if targets else 0
    dp = [float('inf')] * (max_target + 1)
    dp[0] = 0

    for i in range(1, max_target + 1):
        for coin in coins:
            if i >= coin and dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1

    return [dp[t] <= k for t in targets]

