def cheapest_connection(flights, costs, durations):
    from collections import defaultdict
    import heapq

    graph = defaultdict(list)
    for (u, v), cost, duration in zip(flights, costs, durations):
        # Value to minimize: cost + (duration / 60) * 100
        weight = cost + duration * (100 / 60)
        graph[u].append((v, weight, [u, v]))

    # Priority queue stores: (total_weight, current_city, path)
    pq = [(0, "New York", ["New York"])]
    visited = set()

    while pq:
        weight, u, path = heapq.heappop(pq)

        if u == "Melbourne":
            return path

        if u in visited:
            continue
        visited.add(u)

        for v, w, _ in graph[u]:
            if v not in visited:
                heapq.heappush(pq, (weight + w, v, path + [v]))

class TreeNode:

    def __init__(self, x: int):
        self.val = x
        self.left = None
        self.right = None


def has_diff_path(root: TreeNode) -> bool:
    if not root:
        return False

    def get_diff(node):
        if not node:
            return 0
        left_val = node.left.val if node.left else 0
        right_val = node.right.val if node.right else 0
        return abs(left_val - right_val)

    def dfs(node, prev_diff, is_root):
        if not node:
            return False

        current_diff = get_diff(node)
        is_leaf = not node.left and not node.right

        if is_leaf:
            return True if is_root else (current_diff > prev_diff)

        if not is_root and current_diff <= prev_diff:
            return False

        next_diff = current_diff if not is_root else -1

        left_res = (
            dfs(node.left, next_diff, False) if node.left else False
        )
        if left_res:
            return True

        right_res = (
            dfs(node.right, next_diff, False) if node.right else False
        )
        if right_res:
            return True

        return False

    return dfs(root, -1, True)

class TreeNode:
    def __init__(self, x: int):
        self.val = x
        self.left = None
        self.right = None

    def add_node(self, x: int):
        if x < self.val:
            if self.left is None:
                self.left = TreeNode(x)
            else:
                self.left.add_node(x)
        else:
            if self.right is None:
                self.right = TreeNode(x)
            else:
                self.right.add_node(x)

def get_all_elements_in_range(root: TreeNode, range_tuple: tuple) -> set:
    start, end = range_tuple
    result = set()

    if not root:
        return result

    if start <= root.val <= end:
        result.add(root.val)

    if root.val > start:
        result.update(get_all_elements_in_range(root.left, range_tuple))

    if root.val < end:
        result.update(get_all_elements_in_range(root.right, range_tuple))

    return result

