def binary_representations(integers):
    return ((integers[:, None] & (1 << np.arange(7, -1, -1))) > 0).astype(int)

def can_reach_exit(board):
    if not board or not board[0]:
        return False, []

    rows = len(board)
    cols = len(board[0])
    target = (rows - 1, 0)

    def dfs(r, c, path):
        if (r, c) == target:
            return True, path

        max_dist = board[r][c]
        if max_dist == 0:
            return False, []

        # Try moving down
        for step in range(1, max_dist + 1):
            next_r = r + step
            if next_r < rows:
                success, new_path = dfs(next_r, c, path + [(next_r, c)])
                if success:
                    return True, new_path
            else:
                break

        # Try moving right
        for step in range(1, max_dist + 1):
            next_c = c + step
            if next_c < cols:
                success, new_path = dfs(r, next_c, path + [(r, next_c)])
                if success:
                    return True, new_path
            else:
                break

        return False, []

    return dfs(0, 0, [(0, 0)])

