def bonus_calculation(employees: pd.DataFrame, bonus_categories: Dict[str, float], additional_bonus: float) -> Dict[int, int]:
    def calculate_row(row):
        sales = row['total_in_sales']
        salary = row['salary']

        if sales < 10000:
            category = "Low"
        elif 10000 <= sales <= 20000:
            category = "Medium"
        else:
            category = "High"

        base_percentage = bonus_categories.get(category, 0.0)
        total_percentage = base_percentage + (additional_bonus if category == "High" else 0.0)

        return round(salary * total_percentage)

    result_series = employees.apply(calculate_row, axis=1)
    return dict(zip(employees['employee_id'], result_series))

from collections import defaultdict


class BowlingAlley:

    def __init__(self, shoes: list[tuple[int, int]], num_alleys: int):
        self.num_alleys = num_alleys
        self.initial_shoes = defaultdict(int)
        for size, count in shoes:
            self.initial_shoes[size] = count

        self.bookings = {}
        self.schedule = defaultdict(set)
        self.next_booking_id = 1

    def book_alley(self, shoes: list[int], timestamp: int) -> int:
        current_bookings = self.schedule[timestamp]
        if len(current_bookings) >= self.num_alleys:
            return -1

        used_shoes = defaultdict(int)
        for b_id in current_bookings:
            for size in self.bookings[b_id]["shoes"]:
                used_shoes[size] += 1

        requested_shoes = defaultdict(int)
        for size in shoes:
            requested_shoes[size] += 1

        for size, count in requested_shoes.items():
            available = self.initial_shoes[size] - used_shoes[size]
            if count > available:
                return -1

        booking_id = self.next_booking_id
        self.next_booking_id += 1

        self.bookings[booking_id] = {"shoes": shoes, "timestamp": timestamp}
        self.schedule[timestamp].add(booking_id)

        return booking_id

    def delete_booking(self, booking_id: int) -> None:
        if booking_id not in self.bookings:
            return

        booking = self.bookings[booking_id]
        timestamp = booking["timestamp"]

        if timestamp in self.schedule and booking_id in self.schedule[timestamp]:
            self.schedule[timestamp].remove(booking_id)
            if not self.schedule[timestamp]:
                del self.schedule[timestamp]

        del self.bookings[booking_id]

