class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.access_counts = {}

    def get(self, key: int, timestamp: int) -> int:
        if key not in self.cache:
            return -1
        self.access_counts[key] = self.access_counts.get(key, 0) + 1
        return self.cache[key]['value']

    def put(self, key: int, value: int, timestamp: int) -> None:
        if key in self.cache:
            self.cache[key]['value'] = value
            self.access_counts[key] = self.access_counts.get(key, 0) + 1
            return

        if len(self.cache) >= self.capacity:
            candidates = []
            for k, info in self.cache.items():
                age = timestamp - info['insertion_time']
                if age >= 10:
                    accesses = self.access_counts.get(k, 0)
                    rate = accesses / age
                    candidates.append((rate, info['insertion_time'], k))

            if not candidates:
                return

            candidates.sort(key=lambda x: (x[0], x[1]))
            evict_key = candidates[0][2]

            del self.cache[evict_key]
            if evict_key in self.access_counts:
                del self.access_counts[evict_key]

        if len(self.cache) < self.capacity:
            self.cache[key] = {'value': value, 'insertion_time': timestamp}
            self.access_counts[key] = 1

def calculateCommand(currentState, desiredState):
    diff = currentState ^ desiredState
    command = 0
    i = 0
    while i < 32:
        if i == 31:
            if (diff & (1 << 31)):
                command |= (1 << 31)
            i += 1
        else:
            pair_diff = (diff >> i) & 0b11
            if pair_diff == 0b01:
                command |= (0b10 << i)
            elif pair_diff == 0b10:
                command |= (0b01 << i)
            elif pair_diff == 0b11:
                command |= (0b11 << i)
            i += 2
    return command

from typing import List
from collections import deque

def can_exit_maze(maze: List[List[bool]], start: List[int], exit: List[int]) -> bool:
    if not maze or not maze[0]:
        raise ValueError("Maze is empty")

    rows, cols = len(maze), len(maze[0])

    def is_valid(pos):
        return 0 <= pos[0] < rows and 0 <= pos[1] < cols

    if not is_valid(start) or not is_valid(exit):
        raise ValueError("Start or exit position is out of bounds")

    start_r, start_c = start
    exit_r, exit_c = exit

    if maze[start_r][start_c] == 0 or maze[exit_r][exit_c] == 0:
        return False

    queue = deque([start])
    visited = {tuple(start)}

    while queue:
        r, c = queue.popleft()

        if [r, c] == exit:
            return True

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and maze[nr][nc] == 1:
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append([nr, nc])

    return False

def cheapest_connection(nodes: list[int], edges: list[tuple[int, int]]) -> int:
    n = len(nodes)
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    for u, v in edges:
        union(u, v)

    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(nodes[i])

    roots = list(components.keys())
    if len(roots) <= 1:
        return 0

    import heapq

    rep_node_vals = [components[r][0] for r in roots]
    k = len(roots)

    min_edge_to = [float('inf')] * k
    visited = [False] * k

    min_edge_to[0] = 0
    total_cost = 0

    for _ in range(k):
        u = -1
        min_val = float('inf')
        for i in range(k):
            if not visited[i] and min_edge_to[i] < min_val:
                min_val = min_edge_to[i]
                u = i

        if u == -1:
            break

        visited[u] = True
        total_cost += min_val

        val_u = rep_node_vals[u]
        for v in range(k):
            if not visited[v]:
                val_v = rep_node_vals[v]
                cost = val_u ^ val_v
                if cost < min_edge_to[v]:
                    min_edge_to[v] = cost

    return total_cost

def max_reactions(chemicals, reactions):
    from collections import defaultdict

    graph = defaultdict(list)
    in_degree = {chem: 0 for chem in chemicals}

    for u, v in reactions:
        graph[u].append(v)
        in_degree[v] += 1

    # Topological sort
    queue = [chem for chem in chemicals if in_degree[chem] == 0]
    topo_order = []

    while queue:
        node = queue.pop(0)
        topo_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Compute longest paths
    dist = {chem: 0 for chem in chemicals}

    for node in topo_order:
        for neighbor in graph[node]:
            if dist[node] + 1 > dist[neighbor]:
                dist[neighbor] = dist[node] + 1

    return max(dist.values()) if dist else 0

def chess_attacks(board: list[list[str]]) -> bool:
    pieces = {}
    for r in range(8):
        for c in range(8):
            p = board[r][c]
            if p != ".":
                pieces.setdefault(p, []).append((r, c))

    def is_path_clear(r1, c1, r2, c2):
        dr = 0 if r1 == r2 else (1 if r2 > r1 else -1)
        dc = 0 if c1 == c2 else (1 if c2 > c1 else -1)
        curr_r, curr_c = r1 + dr, c1 + dc
        while (curr_r, curr_c) != (r2, c2):
            if board[curr_r][curr_c] != ".":
                return False
            curr_r += dr
            curr_c += dc
        return True

    for p_type, coords in pieces.items():
        for i in range(len(coords)):
            for j in range(i + 1, len(coords)):
                r1, c1 = coords[i]
                r2, c2 = coords[j]
                dr = abs(r1 - r2)
                dc = abs(c1 - c2)

                if p_type == 'K':
                    if max(dr, dc) == 1:
                        return True
                elif p_type == 'N':
                    if (dr == 2 and dc == 1) or (dr == 1 and dc == 2):
                        return True
                elif p_type == 'R':
                    if (r1 == r2 or c1 == c2) and is_path_clear(r1, c1, r2, c2):
                        return True
                elif p_type == 'B':
                    if dr == dc and is_path_clear(r1, c1, r2, c2):
                        return True
                elif p_type == 'Q':
                    if (r1 == r2 or c1 == c2 or dr == dc) and is_path_clear(r1, c1, r2, c2):
                        return True

    return False

class ClosestToKStack:
    def __init__(self, k: int):
        self.k = k
        self.stack = []
        self.min_diff_stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        if not self.min_diff_stack:
            self.min_diff_stack.append(val)
        else:
            current_closest = self.min_diff_stack[-1]
            if abs(val - self.k) < abs(current_closest - self.k):
                self.min_diff_stack.append(val)
            elif abs(val - self.k) == abs(current_closest - self.k):
                if val < current_closest:
                    self.min_diff_stack.append(val)
                else:
                    self.min_diff_stack.append(current_closest)
            else:
                self.min_diff_stack.append(current_closest)

    def pop(self) -> None:
        if self.stack:
            self.stack.pop()
            self.min_diff_stack.pop()

    def top(self) -> int:
        if self.stack:
            return self.stack[-1]
        return -1

    def get_closest_to_k(self) -> int:
        if not self.min_diff_stack:
            return -1
        return self.min_diff_stack[-1]

