def computeIntersectionSurface(square1, square2):
    x_left = max(square1[0], square2[0])
    y_bottom = max(square1[1], square2[1])
    x_right = min(square1[2], square2[2])
    y_top = min(square1[3], square2[3])

    if x_right < x_left or y_top < y_bottom:
        return 0

    return (x_right - x_left) * (y_top - y_bottom)

def compute_modulo(x: int, y: int) -> int:
    if x < y:
        return x

    shift = 0
    while (y << (shift + 1)) <= x:
        shift += 1

    while shift >= 0:
        if (y << shift) <= x:
            x -= (y << shift)
        shift -= 1

    return x
